using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using Xunit;
namespace RPCore.Tests
{
    public class PhoneRefinementTests
    {
        static PhoneData Data()=>new PhoneData{Wallpaper=4,Notes=new List<string>{"Nota antiga"},History=new List<PhoneEntry>{new PhoneEntry{Title="Legado",Body="Texto",Extra=new Dictionary<string,JToken>{{"FutureEntry",true}}}},Extra=new Dictionary<string,JToken>{{"Future","keep"}}};
        [Fact]public void NoteEditsPreserveLegacyHistoryWallpaperAndMetadata(){var d=Data();Assert.True(PhoneEdits.Note(ref d,-1,null,"Nova",n=>{}));Assert.True(PhoneEdits.Note(ref d,1,"Nota antiga","Editada",n=>{}));Assert.True(PhoneEdits.DeleteNote(ref d,0,"Nova",n=>{}));Assert.Equal(new[]{"Editada"},d.Notes);Assert.Equal(4,d.Wallpaper);Assert.Equal("keep",(string)d.Extra["Future"]);Assert.True((bool)d.History[0].Extra["FutureEntry"]);}
        [Theory][InlineData("add")][InlineData("edit")][InlineData("delete")][InlineData("read")][InlineData("wallpaper")][InlineData("append")]
        public void FailedWritesLeaveEntireOriginalUnchanged(string operation){var d=Data();string before=JsonConvert.SerializeObject(d);Action<PhoneData> fail=n=>throw new IOException();Assert.Throws<IOException>(()=>{if(operation=="add")PhoneEdits.Note(ref d,-1,null,"Nova",fail);else if(operation=="edit")PhoneEdits.Note(ref d,0,"Nota antiga","Nova",fail);else if(operation=="delete")PhoneEdits.DeleteNote(ref d,0,"Nota antiga",fail);else if(operation=="read")PhoneEdits.Read(ref d,0,d.History[0],fail);else if(operation=="append")PhoneEdits.Append(ref d,"Novo","Texto","message",fail);else PhoneEdits.Change(ref d,n=>{n.Wallpaper=6;return true;},fail);});Assert.Equal(before,JsonConvert.SerializeObject(d));}
        [Fact]public void StaleNoteConfirmationCannotDeleteChangedNote(){var d=Data();Assert.True(PhoneEdits.Note(ref d,0,"Nota antiga","Alterada",n=>{}));Assert.False(PhoneEdits.DeleteNote(ref d,0,"Nota antiga",n=>throw new Exception()));Assert.Equal("Alterada",d.Notes[0]);}
        [Fact]public void ReadMarksOnlyTheSelectedEntryAndDoesNotClearOtherBadges(){var d=Data();PhoneEdits.Append(ref d,"Nova","Mensagem","message",n=>{});Assert.True(PhoneEdits.Read(ref d,1,d.History[1],n=>{}));Assert.True(d.History[1].Read);Assert.False(d.History[0].Read);}
        [Fact]public void HistorySupportsAllSixtyFourEntriesAndPreservesLegacyInBothViews(){var d=Data();for(int i=0;i<63;i++)PhoneEdits.Append(ref d,"Evento"+i,"Texto",i%2==0?"message":"notification",n=>{});Assert.Equal(64,d.History.Count);Assert.Equal(64,PhoneEdits.History(d,true).Union(PhoneEdits.History(d,false)).Count());Assert.Contains(63,PhoneEdits.History(d,true));Assert.Contains(63,PhoneEdits.History(d,false));Assert.True(PhoneEdits.Append(ref d,"Ultimo","Texto","notification",n=>{}));Assert.Equal(64,d.History.Count);Assert.Equal("Ultimo",d.History[0].Title);}
        [Fact]public void NewlyInsertedHistoryCannotCauseReadToMarkAnotherMessage(){var d=Data();var previous=d.History[0];PhoneEdits.Append(ref d,"Outro","Texto","message",n=>{});Assert.False(PhoneEdits.Read(ref d,0,previous,n=>throw new Exception()));Assert.All(d.History,h=>Assert.False(h.Read));}
        [Theory][InlineData("")][InlineData(" ")][InlineData(null)]public void InvalidNoteTextDoesNotSave(string text){var d=Data();Assert.False(PhoneEdits.Note(ref d,-1,null,text,n=>throw new Exception()));Assert.Single(d.Notes);}
        [Fact]public void NewNoteLimitNeverTruncatesOlderNotes(){var d=Data();while(d.Notes.Count<30)PhoneEdits.Note(ref d,-1,null,"Nota",n=>{});Assert.False(PhoneEdits.Note(ref d,-1,null,"Extra",n=>throw new Exception()));Assert.Equal("Nota antiga",d.Notes[29]);}
        [Fact]public void MalformedOrOversizedListsAreRetainedWithoutRepair(){var d=Data();d.Notes.Add(null);string before=JsonConvert.SerializeObject(d);Assert.False(PhoneEdits.Change(ref d,n=>true,n=>throw new Exception()));Assert.Equal(before,JsonConvert.SerializeObject(d));d=Data();d.History=Enumerable.Range(0,65).Select(i=>new PhoneEntry()).ToList();Assert.False(PhoneEdits.Valid(d));}
        [Fact]public void LongLegacyNoteCanBeViewedWithoutTruncation(){string text=new string('x',1200);Assert.Equal(text,string.Concat(PhoneViewRules.Pages(text)));Assert.All(PhoneViewRules.Pages(text),p=>Assert.InRange(p.Length,1,180));Assert.Single(PhoneViewRules.Pages(null));}
        [Theory][InlineData(0)][InlineData(1)][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)][InlineData(7)][InlineData(8)][InlineData(9)][InlineData(10)][InlineData(11)]
        public void MouseMatchesTheTwelveSourceAppPositions(int index)=>Assert.Equal(index,PhoneViewRules.HomeHit(new PointF(40+index%3*65,160+index/3*65)));
        [Fact]public void GridGapsAndPhoneBorderDoNotSelectApps(){Assert.Equal(-1,PhoneViewRules.HomeHit(new PointF(90,160)));Assert.Equal(-1,PhoneViewRules.HomeHit(new PointF(2,2)));}
        [Fact]public void ListHitUsesScrolledIndexAndRejectsGapsFooterAndOutside(){Assert.Equal(13,PhoneViewRules.RowHit(new PointF(30,82),13,64));Assert.Equal(19,PhoneViewRules.RowHit(new PointF(30,315),13,64));Assert.Equal(-1,PhoneViewRules.RowHit(new PointF(30,114),13,64));Assert.Equal(-1,PhoneViewRules.RowHit(new PointF(30,401),13,64));Assert.Equal(-1,PhoneViewRules.RowHit(new PointF(230,82),13,64));}
        [Fact]public void StopwatchSupportsPauseContinueResetAndMoreThanTwentyFourHours(){var c=new PhoneClockState();c.Stopwatch();c.Advance(1000);c.Stopwatch();c.Advance(1000);Assert.Equal(1000,c.Elapsed);c.Stopwatch();c.Advance(1000);Assert.Equal(2000,c.Elapsed);Assert.Equal("25:00:00",PhoneClockState.Format(90000000));c.ResetStopwatch();Assert.Equal(0,c.Elapsed);Assert.False(c.StopwatchRunning);}
        [Fact]public void TimerAlarmFiresOnceAndDoesNotMintOfflineTime(){var c=new PhoneClockState();Assert.True(c.SetMinutes(1));c.Timer();Assert.False(c.Advance(60000));Assert.Equal(60000,c.Remaining);for(int i=0;i<59;i++)Assert.False(c.Advance(1000));Assert.True(c.Advance(1000));Assert.False(c.Advance(1000));Assert.False(c.TimerRunning);}
        [Theory][InlineData(0)][InlineData(-1)][InlineData(1441)][InlineData(int.MaxValue)]public void InvalidTimerDurationDoesNotModifyCurrentTimer(int minutes){var c=new PhoneClockState();c.SetMinutes(5);c.Timer();Assert.False(c.SetMinutes(minutes));Assert.Equal(300000,c.Remaining);Assert.True(c.TimerRunning);}
        [Theory][InlineData("0")][InlineData("-1")][InlineData("+1")][InlineData("1.5")][InlineData("1e6")][InlineData("2147483648")][InlineData("abc")]public void BankInputRejectsInvalidOrOverflowingAmounts(string text)=>Assert.False(PhoneViewRules.Amount(text,out _));
        [Fact]public void BankMaximumPreventsBalanceAndCashOverflow(){Assert.Equal(25,PhoneViewRules.BankMaximum(100,int.MaxValue-25,true));Assert.Equal(50,PhoneViewRules.BankMaximum(int.MaxValue-50,100,false));Assert.Equal(0,PhoneViewRules.BankMaximum(-1,100,true));Assert.True(PhoneViewRules.Amount(" 1000 ",out int amount));Assert.Equal(1000,amount);}
        [Fact]public void MaximumBankTransferUsesTheExistingCommitAndConservesTotal(){var w=new WalletData{Bank=int.MaxValue-25};int cash=100;int maximum=PhoneViewRules.BankMaximum(cash,w.Bank,true);long total=(long)cash+w.Bank;Assert.True(BankTransfer.Commit(w,()=>cash,n=>cash=n,maximum,true,()=>{}));Assert.Equal(int.MaxValue,w.Bank);Assert.Equal(75,cash);Assert.Equal(total,(long)cash+w.Bank);}
        [Fact]public void PhonePropCopiesCustomBindingAndInvalidTransformFallsBackToPhone(){var original=new PropBinding{Model="my_phone",X=.02f};var copy=PhonePropRules.Resolve(original);Assert.NotSame(original,copy);Assert.Equal("my_phone",copy.Model);copy.X=3;Assert.Equal(.02f,original.X);original.X=float.NaN;Assert.Equal("phonesmart",PhonePropRules.Resolve(original).Model);Assert.Equal("prop_npc_phone_02",PhonePropRules.Resolve(null).Fallback);}
    }
}
